#############################################################################################################################################################################################################
def sel_tile(tile=None):
    if 'CREDO' in SystemHardware.upper():
        return 0
    if tile!=None:
        if type(tile)==list:
            tile=tile[0]
        if tile>3: tile=3
        chip.setTileAddr(tile)
    return chip.tile
    
def sel_group(group=None):
    if group!=None:
        if type(group)==list:
            group = group[0]
        if group>9: group=7
        chip.setPhyAddr(group)
    if  'COWOS' in SystemHardware.upper():
        return chip.group
    else:
        return chip.getPhyAddr()
    
      
def get_tile_list(tile=None):
    if 'CREDO' in SystemHardware.upper():
        return [0]
    if tile == None: tiles = [sel_tile()]#gTiles
    if type(tile) == int:       tiles = [tile]
    elif type(tile) == list:    tiles = tile
    elif type(tile) == str and tile.upper() == 'ALL':
        tiles = range(4)
    tiles=[max(min(x, 3), 0) for x in tiles] # limit tiles numbers between 0 and 3
    return tiles
def get_group_list(group=None):
    if group == None: groups = [sel_group()]#gGroups
    if type(group) == int:       groups = [group]
    elif type(group) == list:    groups = group
    elif type(group) == str and group.upper() == 'ALL':
        groups = range(9)
    groups=[max(min(x, 8), 0) for x in groups] # limit group numbers between 0 and 7
    return groups

def get_lane_list(lane=None):
    if lane == None: lanes = gLanes
    if type(lane) == int:       lanes = [lane]
    elif type(lane) == list:    lanes = lane
    elif type(lane) == str and lane.upper() == 'ALL':
        lanes = range(0, len(lane_name_list))
    lanes=[max(min(x, 7), 0) for x in lanes] # limit lane numbers between 0 and 7
    return lanes

def get_tile_group_lane_list(tile=None, group=None, lane=None):
    tiles  = get_tile_list(tile)
    groups = get_group_list(group)
    lanes  = get_lane_list(lane)
    if (type(tile) == str and tile.upper() == 'ALL') and (group==None) :
        groups = range(8)
        lanes  = range(8)
    if groups[0]==8:
        if len(lanes)>4: lanes=range(4)
    return tiles, groups, lanes
    
def tgl(tile=None,group=None,lane=None):
    global gTiles
    global gGroups
    global gLanes
    if tile is not None:
        if group == None: group = 'all'
        if lane  == None: lane  = 'all'
    gTiles, gGroups, gLanes  = get_tile_group_lane_list(tile, group, lane)
    sel_tile(gTiles[0])
    sel_group(gGroups[0])
    return gTiles,gGroups,gLanes
    
##############################################################################
def watch(function,*args):
    import os
    os.system('cls' if os.name == 'nt' else 'clear')
    try:
        while True:            
            print('\033[0;0H') # go to top left corner of screen
            print('\033[f') # go to top left corner of screen
            function(*args)
            time.sleep(1)            
    except KeyboardInterrupt:
        pass
       
def watch_group(function1, function2):
    import os
    os.system('cls' if os.name == 'nt' else 'clear')
    try:
        while True:            
            print('\033[0;0H') # go to top left corner of screen
            print('\033[f') # go to top left corner of screen
            function1(None)
            function2(None)
            time.sleep(1)            
    except KeyboardInterrupt:
        pass
