def temp_sensor(tile=None, print_en=1):
    tiles=get_tile_list(tile)
    for tl in tiles:
        sel_tile(tl)
        sel_group(9)
        temp_sensor_start()
        value1 = temp_sensor_read(auto=0, print_en=print_en)
        print('...Tile %d TempSensor: %3.1f C' % (tl,value1)),

##########################################################################
# Set up On-Chip Temperature Sensor (to be read later)
#
##########################################################################
def temp_sensor_start():
    base = 0x4B00
    #chip.MdioWr(0x4d00, 0x5d81)
    chip.TILE_TOP[0].PD_CAL_FCAL = 0

    chip.TILE_TOP[0].TSENSOR_AUTO_EN = 1
    chip.TILE_TOP[0].VSENSOR_AUTO_EN = 1
    chip.TILE_TOP[0].VSENSOR1_AUTO_EN = 1
    chip.TILE_TOP[0].TSENSOR_RSTB = 1
    chip.TILE_TOP[0].VSENSOR_RSTB = 1
    chip.TILE_TOP[0].VSENSOR1_RSTB = 1

    #chip.MdioWr(base + 0x3e, 0x0054)  # set clock
    chip.TILE_TOP[0].VSENSOR_CLK_SEL = 0
    chip.TILE_TOP[0].VSENSOR_CLK_CNTR = 0x54
    time.sleep(1)
    #chip.MdioWr(base + 0x37, 0x0)  # reset sensor
    chip.TILE_TOP[0].TSENSOR_RUN = 0
    chip.TILE_TOP[0].TSENSOR_RSTN = 0
    chip.TILE_TOP[0].TSENSOR_PD = 0
    time.sleep(1)

