    tiles, groups, lanes  = get_tile_group_lane_list(tile, group, lane)
    get_lane_mode(tiles, groups, lanes)  # updates gEncodingMode real time based on the actual setting of the chip
    for tl in tiles:
        sel_tile(tl)
        for grp in groups:
            sel_group(grp)
            fw_load_status = fw_loaded(print_en=False)
            if not fw_load_status:
                prefix = "Tile " + str(tl) + ", Group " + str(grp)
