    product_name = 'BlueJay'
    #Vsensor_base_addr = 0x4B00  # BlueJay's On-chip Vsensor. Used for measuring test point output voltage
    TX_PLL_LANE_EN = chip.LANE[lane].TX_PLL_EST_EN
    TX_PLL_LANE_GRP = chip.LANE[lane].TX_PLL_VTSTGROUP
    TX_PLL_LANE_TPMODE = chip.LANE[lane].TX_PLL_TESTMODE
    RX_PLL_LANE_EN = chip.LANE[lane].RX_PLL_TEST_EN
    RX_PLL_LANE_GRP = chip.LANE[lane].RX_PLL_VTSTGROUP
    RX_PLL_LANE_TPMODE = chip.LANE[lane].RX_PLL_TESTMODE
    TX_LANE_EN = chip.LANE[lane].TX_TEST_GROUP_EN
    TX_LANE_GRP = chip.LANE[lane].TX_VTSTGROUP
    TX_LANE_TPMODE = chip.LANE[lane].TX_TESTMODE
    RX_LANE_EN = chip.LANE[lane].RX_TEST_GROUP_EN
    RX_LANE_GRP = chip.LANE[lane].RX_VTSTGROUP
    RX_LANE_TPMODE = chip.LANE[lane].RX_TESTMODE
    tp_list = []
    # TEST_GRP_NAME    NUM_TPs, TP Enable, TP GRP Num,  TP Mode (PGATE,PMOS,NMOS)
    tp_list.append(['TX_PLL_LANE', 32, TX_PLL_LANE_EN, TX_PLL_LANE_GRP, TX_PLL_LANE_TPMODE])
    tp_list.append(['RX_PLL_LANE', 16, RX_PLL_LANE_EN, RX_PLL_LANE_GRP, RX_PLL_LANE_TPMODE])
    tp_list.append(['TX_LANE', 16, TX_LANE_EN, TX_LANE_GRP, TX_LANE_TPMODE])
    tp_list.append(['RX_LANE', 64, RX_LANE_EN, RX_LANE_GRP, RX_LANE_TPMODE])
    print("\n....Test Point Options for %s:" % product_name)
    for grp in range(len(tp_list)):
        print("\n    meas_tp( tp_name='%-13s' ,lane= [0,%d] ,tp_num=0 to %d, tp_mode= 'PMOS/NMOS/PGATE' )  # Test Group %d" % (
            tp_list[grp][0], len(lane_name_list), tp_list[grp][1] - 1, grp)),

    print("\n\n....Test Group Options for %s:" % product_name)
    for grp in range(len(tp_list)):
        print("\n    meas_tp_grp( tp_grp='%-13s' ,lane= [0,%d] ,'log_en=1')  # Test Group %d, %d Test Points" % (
        tp_list[grp][0], len(lane_name_list), grp, tp_list[grp][1])),

