def bg_rx_cal(tile=None, group=None, lane=None, tp_modes=['PGATE'], print_en=1):
    #tiles, groups, lanes  = get_tile_group_lane_list(tile, group, lane)
    tiles = tile
    groups = group
    lanes = lane

    for tl in tiles:
        sel_tile(tl)
        for grp in groups:
            sel_group(grp)
            for ln in lanes:
                print ('\nTGL: %d%d%d RX BG: '%(tl,grp, ln)),
                bg_val=0
                while bg_val<=7:
                    chip.NRZ25[ln].RX_VBG = bg_val
                    RxBandgapMap[tl][grp][ln] = bg_val
                    time.sleep(.01)
                    rx_bg = meas_bg_rx(group=grp, lane=ln, tp_modes=tp_modes, print_en=0)[ln][0]
                    print ('(%d,%3.0fmV)'%(bg_val,rx_bg)),
                    if rx_bg >= 740 or bg_val==7:
                        break
                    if rx_bg < 730 :# and bg_val <= 5:
                        bg_val += int((740-rx_bg)/10)
                        if bg_val>7: bg_val=7                   
                    else:
                        bg_val+=1

