def wb_setup():
    time_stamp = datetime.datetime.now(tz=pytz.timezone('US/Pacific')).strftime(u"%Y%m%d_%H%M")
    pwd = str(os.path.dirname(os.path.realpath(__file__)))
    new_path = pwd + '/../TestResult/'
    if not os.path.exists(new_path):
        os.makedirs(new_path)
    file_name = "BJ_LT_LOG_" + time_stamp + ".xlsx"
    # log_name = "BE_BH" + ".log"
    # f_log = open(os.path.join(new_path, log_name), "w")
    chip.log_path = new_path

    wb = Workbook()
    wb.fname = os.path.join(new_path, file_name)
    ws = wb.active
    ws.append(["Opt Param"])
    ws.append(["Index", "Field", "Value"])
    wb.save(wb.fname)
    return wb

def LT_fw_params():
    opt_param = list()  # LT Opt algorithm parameters
    opt_param.append((107, 'FFE_adapt_iter', 1))
    opt_param.append((115, 'FFE_freeze', 0xf))  # lane encode
    opt_param.append((11, 'lane_fwbp_en', 0x0))
    opt_param.append((170, 'dac_tgt_final', 10))
    opt_param.append((171, 'tx_adjust_num', 20))
    opt_param.append((172, 'tx_adjust_fm1_thre', 40))
    opt_param.append((173, 'lt3_success_cnt', 20))
    opt_param.append((174, 'lt3_timeout_cnt', 200))
    opt_param.append((16, 'target_agcgain1', 64))
    opt_param.append((175, 'opt_freeze', 0))  # lane encode
    opt_param.append((176, 'ratio_factor', 64))
    opt_param.append((177, 'opt_restart', 0))  # lane encode
    opt_param.append((121, 'fit_eye_margin_start', 105))
    opt_param.append((122, 'fit_off_margin_check', 40))
    opt_param.append((178, 'linear_fit_on', 0xf)) # lane encode
    opt_param.append((13, 'lane_fwbp_lvl', 0))
    opt_param.append((185, 'lt_nrz_stage_en', 0xffdf))
    opt_param.append((186, 'lt_pam4_stage_en', 0x800f))  #LT3 + LF + FFE
    return opt_param




