def LT_init(tile=None, group=None, lane=None, mode=None, input_mode='ac' ):
    
    PHY_adapt_init(tile, group, lane, mode, input_mode )
 
def LT_start(tile=None, group=None, lane=None, mode='PAM4'):
    print_en=1

    #tiles, groups, lanes  = get_tile_group_lane_list(tile, group, lane)
    if print_en:
        prefix = "\n...Tiles: " + str(tile) + ", Groups: " + str(group) + ", Lanes: " + str(lane)
        print("%s -- Starting LinkTraining in %4s Mode."%(prefix,mode)),

    for x in range(len(lane)):
        tl  = sel_tile ( tile[x])
        grp = sel_group(group[x])
        ln  = lane[x]
        
        for param in LT_fw_params():
            idx   = int(param[0])
            field = param[1]
            val   = int(param[2])
            #print("\tTGL (%d,%d,%d): @%d: %s = %d" % (tl,grp,ln,idx, field, val))
            fw_reg(idx, val)

        # AA HCD Overwrite 1
        #wreg(0x602 + (0x800*ln), 0xc0)
        chip.ANLT_TOP[ln].HCD_BIT_OW_EN = 0
        chip.ANLT_TOP[ln].FEC_RESOLUTION_OW_EN = 0
        chip.ANLT_TOP[ln].FEC_RS_OW_VAL = 0
        chip.ANLT_TOP[ln].FEC_KR_OW_VAL = 0
        chip.ANLT_TOP[ln].HCD_BIT_OW_VAL_BIT_4_1 = 0
        chip.ANLT_TOP[ln].AA_HCD_RESOLVED_S_OW_EN = 1
        chip.ANLT_TOP[ln].AA_HCD_RESOLVED_S_OW_VAL = 1
        chip.ANLT_TOP[ln].AA_AN_LINK_GOOD_S_OW_EN = 0
        chip.ANLT_TOP[ln].AA_AN_LINK_GOOD_S_OW_VAL = 0
        chip.ANLT_TOP[ln].AA_MR_AUTONEG_COMPLETE_S_OW_EN = 0
        chip.ANLT_TOP[ln].AA_MR_AUTONEG_COMPLETE_S_OW_VAL = 0
        chip.ANLT_TOP[ln].DIS_BP_FEC_BITS_FOR_CONSORTIUM_SPEED = 0
        chip.ANLT_TOP[ln].HCD_BIT_OW_VAL_BIT_0 = 0
        #set lane polarity
        #if(tl==3): chip.NRZ25[ln].TX_ANA_OUT_FLIP = 0
        #if(tl==1): chip.NRZ25[ln].TX_ANA_OUT_FLIP = 1
        #set phy speed to default (cmd_detail)
        #wreg(0x40C2, 0)
        #send firmware command for PAM4 LT (cmd)
        #wreg(0x40C1, (0x80E0+ln))
        
        ### FW Command for putting a lane in LT mode
        fw_config_cmd(config_cmd=0x80E0+ln, config_detail=0x0000)
            
def LT_done_wait(tile=None, group=None, lane=None, mode='PAM4',timeout=20.0):
    print_en=1
    #tiles, groups, lanes  = get_tile_group_lane_list(tile, group, lane)
    if print_en:
        prefix = "\n...Tiles: " + str(tile) + ", Groups: " + str(group) + ", Lanes: " + str(lane)
        print("%s -- Waiting For %s LinkTraining to Complete\n"%(prefix,mode))
    start=time.time()
    TL_done =[False,False]
    TL_dbg  =[0,0]
    TL_tx_taps =[[90,91,92,93,94],[80,81,82,83,84]]
    try :
        while True:
            if not False in TL_done: 
                break
            if time.time()-start > timeout: 
                print ("\n\n...LT Timed Out!!!\n\n")
                break
            sel_tile ( tile[0])
            sel_group(group[0])
            hive_lt   = chip.ANLT_TOP[lane[0]]
            hive_nrz  = chip.NRZ25[lane[0]]
            hive_pam4 = chip.PAM50[lane[0]]
            TL_tx_taps[0][0] = utos(hive_nrz.KR_SM_COEF_M2,6)
            TL_tx_taps[0][1] = utos(hive_nrz.KR_SM_COEF_M1,6)
            TL_tx_taps[0][2] = hive_nrz.KR_SM_COEF_0
            TL_tx_taps[0][3] = utos(hive_nrz.KR_SM_COEF_1,6)
            TL_dbg[0] = fw_debug(lane[0], 0, 50)
            if(TL_dbg[0]==0x6000): TL_done[0] = True
            
            sel_tile ( tile[1])
            sel_group(group[1])
            hive_lt   = chip.ANLT_TOP[lane[1]]
            hive_nrz  = chip.NRZ25[lane[1]]
            hive_pam4 = chip.PAM50[lane[1]]
            TL_tx_taps[1][0] = utos(hive_nrz.KR_SM_COEF_M2,6)
            TL_tx_taps[1][1] = utos(hive_nrz.KR_SM_COEF_M1,6)
            TL_tx_taps[1][2] = hive_nrz.KR_SM_COEF_0
            TL_tx_taps[1][3] = utos(hive_nrz.KR_SM_COEF_1,6)
            TL_dbg[1] = fw_debug(lane[1], 0, 50)
            if(TL_dbg[1]==0x6000): TL_done[1] = True
            
            print (("...LT Progess Status:   TGL[%d,%d,%d]: ")%(tile[0],group[0],lane[0]) + str(hex(TL_dbg[0])) +
                   ("  TX(%2d,%3d,%2d,%3d) ") % (TL_tx_taps[0][0],TL_tx_taps[0][1],TL_tx_taps[0][2],TL_tx_taps[0][3]) + 
                   ("<--> TX(%d,%3d,%2d,%3d) TGL[%d,%d,%d]  ")%(TL_tx_taps[1][0],TL_tx_taps[1][1],TL_tx_taps[1][2],TL_tx_taps[1][3],tile[1],group[1],lane[1]) + str(hex(TL_dbg[1]))+ "\r"),
        
       
        
            time.sleep(.1)
    except KeyboardInterrupt:
        pass

