class MyPrompt(Prompts):
     def in_prompt_tokens(self, cli=None):
         global stored_prompt_num
         global stored_tile_num; 
         global stored_group_num;
         if stored_prompt_num!=self.shell.execution_count :
            #if 'COWOS' in hw_system.upper():
            stored_tile_num = sel_tile() #chip.tile
            stored_group_num = sel_group() #chip.group
            # elif 'CREDO' in hw_system.upper():
                # stored_tile_num =0
                # stored_group_num = 
            stored_prompt_num = self.shell.execution_count
         return [(Token, (SystemHardware+"/tile"+str(stored_tile_num)+"/group"+str(stored_group_num)+"/lane"+str(current_lane))),
                 (Token.Prompt, ' \nIn [%d]:'%self.shell.execution_count)]

@register_line_magic                
def tile(line):
    if int(line) < 4 :
        #chip.setTileAddr(int(line))
        sel_tile(int(line))
    else :
        print("Error")
        
del tile

@register_line_magic                
def group(line):
    if int(line) < 9:
        #chip.setPhyAddr(int(line))
        sel_group(int(line))
    else :
        print("Error")
        
del group
           
@register_line_magic                
def goto(line):
    level_list = []
    global current_lane
    for level in range(line.count("/")+1):
        try:
            int(line.split("/")[level])
        except:
            print ("Error(1)")
        level_list.insert(0, int(line.split("/")[level]))
    #print (level_list)
    cnt = 0
    for level in level_list :
        if cnt == 0: 
            if level<8 and level>=0:
                current_lane = level
                cnt += 1
            else:
                print ("Error(2)")
        elif cnt == 1:
            if level<8 and level>=0:
                #chip.setPhyAddr(level)
                sel_group(level)
                cnt += 1
            else:
                print ("Error(3)")
        elif cnt == 2:
            if level<4 and level>=0:
                #chip.setTileAddr(level)
                sel_tile(level)
                cnt +=1
            else:
                print ("Error(4)")
        else:
            print ("Error(5)")
        

del goto
