## Initialize the System Variables
##########################################################################
def init_system(hw_system = SystemHardware):

    ####### Initialize Variables
    global gEncodingMode; gEncodingMode = []
    for tl in range(4):
        gEncodingMode.append([])
        for grp in range(9):
            gEncodingMode[tl].append([])
            for ln in range(8):
                gEncodingMode[tl][grp].append(decode_lane_mode(25))

    ####### Initialize MDIO and Chip based on Credo EVB or System with CoWoS ASIC
    if 'CREDO' in hw_system.upper():
        print("\n...%s Eval Board is Selected...\n"%(hw_system))
        #chip.disconnect()
        chip.connect(mdio=False,mode=3)
        sel_tile(0)    
        log_to_phy_lane_mapping_table (hw_system=hw_system) # No Logical-to-Phyical Lane Mappring for  Credo SMK EVB and QSFP EVB
        init_log_to_phy_reg_range    (tile='all', group='all', lane='all', print_en=True)
        init_log_to_phy_lane_mapping (tile='all', group='all', lane='all', print_en=True)
        init_pol                     (tile='all', group='all', lane='all', print_en=True) # Lane TX/RX Polarities for Credo SMK EVB and QSFP EVB
        lane_partner_table  (hw_system=hw_system)           # Lane Partners for Credo SMK EVB and QSFP EVB        

    elif  'COWOS' in hw_system.upper():
        print("\n...CoWoS System Newport #2 (with cables) Selected...\n")
        from credoSock import Mdio_sock, Mdio_pcie
        chip.connect()
        sel_tile(0) 
        log_to_phy_lane_mapping_table(hw_system=hw_system) # Logical-to-Phyical Lane Mappring for CoWos Board
        init_log_to_phy_reg_range    (tile='all', group='all', lane='all', print_en=True)
        init_log_to_phy_lane_mapping (tile='all', group='all', lane='all', print_en=True)
        init_pol                     (tile='all', group='all', lane='all', print_en=True)  # Lane TX/RX Polarities for CoWos Board Newport2
        lane_partner_table (hw_system=hw_system)           # CoWos Board Newport2 with cables on all ports   


        
    sel_tile(0)
    sel_group(0)
    
    ip = get_ipython()
    ip.prompts = MyPrompt(ip)
    #init_bluejay()
