g_cur_tile = 0
g_cur_grp = 0

def bfn_config_lane_AN(capability, tile=None, group=None, lane=None, LT=1, consort=None, is_loop=True, input_mode='ac'):
    tiles = [tile]
    groups = [group]
    lanes  = [lane]

    fw_reload = 'bluejay.1.00.10.fw.bin'
    power_up_init  ( tile, group, lane, fw_reload)

    if type(capability)==str or type(capability)==list:
        basepage = translate_basepage(capability)
        basepage |= 1       # IEEE 802.3
    else:
        basepage = capability
    consort=translate_consort(consort)

    encoding_mode = ["an", 0]
    mode = encoding_mode[0]
    datarate = encoding_mode[1]

    # Deconfig first.
    for tl in tiles:
        sel_tile(tl)
        for grp in groups:
            sel_group(grp)
            for ln in lanes:
                fw_config_cmd(0x90D0+ln, config_detail=0)
                gEncodingMode[tl][grp][ln]=encoding_mode

                # AN mode settings
                wreg(0x310, basepage&0xffff, lane=ln)
                wreg(0x311, (basepage>>16)&0xffff, lane=ln)
                wreg(0x312, (basepage>>32)&0xffff, lane=ln)
                if consort==0:
                    wregBits(0x600, [12], 1, lane=ln)
                else:
                    wregBits(0x600, [12], 0, lane=ln)
                    wreg(0x3f4, consort, lane=ln)
                wregBits(0x600, [10], 1 if is_loop else 0, lane=ln)
    # Then config
    for tl in tiles:
        sel_tile(tl)
        for grp in groups:
            sel_group(grp)
            for ln in lanes:
                fw_config_lane(mode=mode, datarate=datarate, LT=LT, lane=ln)

