# bfn_tx_eq_dump
#
# Dump PRE/MAIN/POST values of all lanes
#
def bfn_tx_eq_dump(tile_list, grp_list, ln_list):
  for tile in tile_list:
    print("Tile " + str(tile) + ":")
    print("+------+-----------------+----------------+----------------+----------------+----------------+----------------+----------------+----------------+")
    for g in grp_list:
      print("| grp" + str(g) + " | "),
      for ln in ln_list:
        pre, main, post = bfn_tx_eq_get(tile, g, ln)
        print("%04x"%pre + "-%04x"%main + "-%04x |"%post),
      print("")
  print("+------+-----------------+----------------+----------------+----------------+----------------+----------------+----------------+----------------+")

