# bfn_config_grps_nrz
#
# Configure NRZ on all lanes of the tile and group list
#
def bfn_config_grps_nrz(tile, grp_list, prbs_mode='PRBS31', speed=25):
  for g in grp_list:
    bfn_config_lanes_nrz(tile, g, range(8), prbs_mode, speed)

