def bfn_rx_monitor_lanes(tile, g, ln_list, dwell=0.1):
  set_tile(tile)
  set_grp(g)

  for ln in ln_list:
    rx_monitor(rst=1, tile=tile, group=g, lane=ln, print_en=0, capture_en=0)
    time.sleep(dwell)
    rx_monitor(rst=0, tile=tile, group=g, lane=ln, print_en=0, capture_en=1)
  print("Tile " + str(tile) + " Grp" + str(g) + ":")
  rx_monitor(rst=0, tile=tile, group=g, lane=ln_list, print_en=1, capture_en=0)
    
