  ctle_val = chip.PAM50[ln].ctle_pam4(); ctle_1 = chip.PAM50[ln].ctle_map_pam4(ctle_val)[0]; ctle_2 = chip.PAM50[ln].ctle_map_pam4(ctle_val)[1]
