def TEST_sensors():
  """
  banner("Temp sensor read (Auto=1)")
  temp_sensor(auto=1)
  print("")
  """

  banner("Temp sensor read (Auto=0)")
  temp_sensor(tile=0)
  print("")
  exit()

  for check in range(5):
    print("Power-dn + " + str(check) + " seconds..")
    temp_sensor(tile=0)
    print("")

  for tile in bfn_working_tiles:
    set_tile(tile)
    static_power_down_broadcast_mode(tile=tile, group=range(8), lanes =range(8))

  for check in range(5):
    print("Power-dn + " + str(check) + " seconds..")
    temp_sensor(tile=tile)
    print("")

  print("Power-Up erdes again..")
  for tile in bfn_working_tiles:
    set_tile(tile)
    for g in range(8):
      set_grp(g)
      # power back up
      static_power_down(group=g, lane=range(8), rx_off=0, tx_off=0, rx_bg_off=0 , tx_bg_off=0)

